sect3.example:
    Typed pass-by-reference Parameters


<?php
function array_baz(array &$param)
{
    $param = 1;
}
$var = [];
array_baz($var);
var_dump($var);
array_baz($var);
?>


    &example.outputs.similar;


int(1)

Fatal error: Uncaught TypeError: array_baz(): Argument #1 ($param) must be of type array, int given, called in - on line 9 and defined in -:2
Stack trace:
#0 -(9): array_baz(1)
#1 {main}
  thrown in - on line 2

note.example:
      Arguments लाई nullable बनाउने पुरानो तरिका (Old way to make arguments nullable)


<?php
class C {}

function f(C $c = null) {
    var_dump($c);
}

f(new C);
f(null);
?>


      &example.outputs;


object(C)#1 (0) {
}
NULL

sect3.para:
    उदाहरणका लागि, यदि A र B class aliases हुन् भने, A|B एक कानुनी union type रहन्छ, यद्यपि यसलाई घटाएर A वा B मा सीमित गर्न सकिन्थ्यो।
    त्यस्तै गरी, यदि class B extends A {} छ भने, A|B पनि एक कानुनी union type हो, यद्यपि यसलाई केवल A मा घटाउन सकिन्थ्यो।




<?php
function foo(): int|INT {} // Disallowed (अनुमति छैन)
function foo(): bool|false {} // Disallowed (अनुमति छैन)
function foo(): int&Traversable {} // Disallowed (अनुमति छैन)
function foo(): self&Traversable {} // Disallowed (अनुमति छैन)

use A as B;
function foo(): A|B {} // Disallowed ("use" name resolution को भाग हो)
function foo(): A&B {} // Disallowed ("use" name resolution को भाग हो)

class_alias('X', 'Y');
function foo(): X|Y {} // Allowed (redundancy रनटाइममा मात्र थाहा हुन्छ)
function foo(): X&Y {} // Allowed (redundancy रनटाइममा मात्र थाहा हुन्छ)
?>

sect1.sect2:
  &reftitle.examples;

   आधारभूत class type declaration (Basic class type declaration)


<?php
class C {}
class D extends C {}

// यसले C लाई विस्तार गर्दैन।
class E {}

function f(C $c) {
    echo get_class($c)."\n";
}

f(new C);
f(new D);
f(new E);
?>


   &example.outputs.8;


C
D

Fatal error: Uncaught TypeError: f(): Argument #1 ($c) must be of type C, E given, called in /in/gLonb on line 14 and defined in /in/gLonb:8
Stack trace:
#0 -(14): f(Object(E))
#1 {main}
  thrown in - on line 8





   आधारभूत interface type declaration (Basic interface type declaration)


<?php
interface I { public function f(); }
class C implements I { public function f() {} }

// यसले I लाई कार्यान्वयन गर्दैन।
class E {}

function f(I $i) {
    echo get_class($i)."\n";
}

f(new C);
f(new E);
?>


   &example.outputs.8;


C

Fatal error: Uncaught TypeError: f(): Argument #1 ($i) must be of type I, E given, called in - on line 13 and defined in -:8
Stack trace:
#0 -(13): f(Object(E))
#1 {main}
  thrown in - on line 8





   आधारभूत return type declaration (Basic return type declaration)


<?php
function sum($a, $b): float {
    return $a + $b;
}

// ध्यान दिनुहोस् कि float फर्काइनेछ।
var_dump(sum(1, 2));
?>


   &example.outputs;


float(3)





   Object फर्काउने उदाहरण (Returning an object)


<?php
class C {}

function getC(): C {
    return new C;
}

var_dump(getC());
?>


   &example.outputs;


object(C)#1 (0) {
}





   Nullable argument type declaration


<?php
class C {}

function f(?C $c) {
    var_dump($c);
}

f(new C);
f(null);
?>


   &example.outputs;


object(C)#1 (0) {
}
NULL





   Nullable return type declaration


<?php
function get_item(): ?string {
    if (isset($_GET['item'])) {
        return $_GET['item'];
    } else {
        return null;
    }
}
?>





   Class property type declaration


<?php
class User {
    public static string $foo = 'foo';

    public int $id;
    public string $username;

    public function __construct(int $id, string $username) {
        $this->id = $id;
        $this->username = $username;
    }
}
?>

sect2.example:
   Arguments का मानहरूका लागि Strict typing


<?php
declare(strict_types=1);

function sum(int $a, int $b) {
    return $a + $b;
}

var_dump(sum(1, 2));
var_dump(sum(1.5, 2.5));
?>


   &example.outputs.8;


int(3)

Fatal error: Uncaught TypeError: sum(): Argument #1 ($a) must be of type int, float given, called in - on line 9 and defined in -:4
Stack trace:
#0 -(9): sum(1.5, 2.5)
#1 {main}
  thrown in - on line 4

   Argument मानहरूका लागि Coercive typing


<?php
function sum(int $a, int $b) {
    return $a + $b;
}

var_dump(sum(1, 2));

// यी मानहरूलाई integers मा जबरजस्ती ढाल्नेछ (coerced हुनेछ): तलको आउटपुट हेर्नुहोस्!
var_dump(sum(1.5, 2.5));
?>


   &example.outputs;


int(3)
int(3)

   Return values का लागि Strict typing


<?php
declare(strict_types=1);

function sum($a, $b): int {
    return $a + $b;
}

var_dump(sum(1, 2));
var_dump(sum(1, 2.5));
?>


   &example.outputs;


int(3)

Fatal error: Uncaught TypeError: sum(): Return value must be of type int, float returned in -:5
Stack trace:
#0 -(9): sum(1, 2.5)
#1 {main}
  thrown in - on line 5
